<script setup lang="ts">
import type { MapLayer } from '~/types/community'
import { errorMessage } from '~/utils/format'
const layers=defineModel<MapLayer[]>({required:true}),hd=defineModel<boolean>('hd',{default:false})
const props=defineProps<{getBounds?:()=>{west:number;south:number;east:number;north:number;zoom:number}|undefined}>()
const open=ref(false),error=ref(''),saving=ref('')
const bounds=useState('map-cache-bounds',()=>({west:88.88,south:29.26,east:88.91,north:29.29,zoom:16}))
const baseLayers=computed(()=>layers.value.filter(x=>!x.annotation)),annotations=computed(()=>layers.value.filter(x=>x.annotation))
async function save(layer:MapLayer,changes:Partial<MapLayer>){saving.value=layer.id;error.value='';try{const result=await $fetch<MapLayer>('/api/map/layers',{method:'POST',body:{...layer,...changes},retry:0});layers.value=layers.value.map(x=>x.id===layer.id?result:x)}catch(e){error.value=errorMessage(e)}finally{saving.value=''}}
function remember(){const current=props.getBounds?.();if(current)bounds.value=current}
</script>
<template><div class="layer-dock" :class="{expanded:open}"><button class="layer-handle" aria-label="图层" :aria-expanded="open" @click="open=!open"><span>🗺️</span><small>{{ open?'收起':'图层' }}</small></button><div v-if="open" class="layer-strip"><button v-for="layer in baseLayers" :key="layer.id" class="layer-tile" :class="{active:layer.enabled}" :disabled="!!saving" @click="save(layer,{enabled:!layer.enabled})"><span :class="{satellite:layer.id==='jlyh'}">{{ layer.id==='jlyh'?'':'🗺️' }}</span><small>{{ layer.name }}</small></button><div class="layer-toggles"><UCheckbox v-for="layer in annotations" :key="layer.id" :label="layer.name" :model-value="layer.enabled" :disabled="!!saving" @update:model-value="v=>save(layer,{enabled:!!v})" /><UCheckbox v-model="hd" label="高清" /></div><NuxtLink to="/layers?from=map" class="layer-settings" @click="remember"><UIcon name="i-lucide-settings" /><small>设置</small></NuxtLink></div><p v-if="error" class="layer-error">{{ error }}</p></div></template>
<style scoped>.layer-dock{position:absolute;left:max(12px,calc(100% - 365px));right:auto;bottom:34px;z-index:15;display:flex;align-items:stretch;border:1px solid #e1e5e1;background:white;border-radius:13px;box-shadow:0 4px 18px #17211e25;max-width:min(300px,calc(100% - 77px))}.layer-handle{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:8px 14px;min-width:62px}.layer-handle span{font-size:27px}.layer-handle small,.layer-tile small,.layer-settings small{font-size:12px;white-space:nowrap}.layer-strip{display:flex;gap:10px;align-items:center;padding:7px 10px 7px 0;overflow:auto}.layer-tile{display:flex;flex-direction:column;gap:2px;align-items:center;min-width:66px;color:var(--text-3)}.layer-tile>span{display:flex;align-items:center;justify-content:center;width:50px;height:41px;font-size:25px;background:#f1f4f0;border:2px solid transparent;border-radius:8px}.layer-tile.active{color:#176ce7}.layer-tile.active>span{border-color:#176ce7}.layer-tile>span.satellite{background:linear-gradient(25deg,#465e28 20%,#74903f 23%,#334e2d 45%,#657a47 47%,#2f4a34 65%,#88a38a 67%,#4e6d48)}.layer-toggles{display:flex;flex-direction:column;gap:7px;white-space:nowrap;min-width:86px}.layer-settings{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;width:40px;color:var(--text-3)}.layer-settings .iconify{width:23px;height:23px}.layer-error{position:absolute;bottom:100%;right:0;background:white;padding:10px;color:var(--danger);border-radius:8px;min-width:220px}@media(max-width:600px){.layer-dock{left:max(12px,calc(100% - 365px));right:auto;bottom:34px;max-width:calc(100% - 77px)}.layer-handle{min-width:52px;padding:5px 8px}.layer-strip{gap:7px}.layer-tile{min-width:58px}.layer-toggles{min-width:80px}}</style>
